import{_ as a,o,c as r,a6 as t}from"./chunks/framework.QBF2cGGQ.js";const d=JSON.parse('{"title":"12 · 产品与场景","description":"","frontmatter":{},"headers":[],"relativePath":"guide/12-product.md","filePath":"guide/12-product.md","lastUpdated":1793327470000}'),i={name:"guide/12-product.md"};function n(p,s,l,e,c,u){return o(),r("div",null,[...s[0]||(s[0]=[t('<h1 id="_12-·-产品与场景" tabindex="-1">12 · 产品与场景 <a class="header-anchor" href="#_12-·-产品与场景" aria-label="Permalink to &quot;12 · 产品与场景&quot;">​</a></h1><blockquote><p><strong>贯穿全局</strong> · 技术选错的成本可以挽回，场景选错基本等于项目失败。 这一层决定你是在做有价值的东西还是在做玩具。</p></blockquote><h2 id="判断标准" tabindex="-1">判断标准 <a class="header-anchor" href="#判断标准" aria-label="Permalink to &quot;判断标准&quot;">​</a></h2><p>一个场景值不值得做 AI，我通常看三条：任务本身是不是&quot;模糊输入 → 模糊输出&quot;（确定性的活交给规则引擎更便宜）；错误成本高不高（高的话必须有人工兜底）；有没有验证手段（不能验证的场景，你永远不知道做得好不好）。</p><p>三条都过，才值得投入。只过一条的，基本会变成演示品。</p><h2 id="场景判断" tabindex="-1">场景判断 <a class="header-anchor" href="#场景判断" aria-label="Permalink to &quot;场景判断&quot;">​</a></h2><ul><li><strong>适合 LLM 的四类任务</strong> <span class="prio prio-must">必须</span> — 文本理解与生成、非结构化转结构化、多义匹配、开放式建议。</li><li><strong>不适合的四类</strong> <span class="prio prio-must">必须</span> — 精确计算、强实时、零容错、需要可解释审计。</li><li><strong>&quot;AI 含量&quot;过高的伪需求</strong> <span class="prio prio-must">必须</span> — 用户真正要的可能是规则引擎或搜索，不是聊天机器人。</li><li><strong>任务的可验证性</strong> <span class="prio prio-must">必须</span> — 输出能不能被自动或低成本人工验证？不能验证的场景慎入。</li><li><strong>人机边界设计</strong> <span class="prio prio-must">必须</span> — 哪些环节必须人来定，哪些可以全自动。这条线划错，产品要么危险要么没用。</li><li><strong>频率与价值密度</strong> <span class="prio prio-imp">重要</span> — 高频低价值（成本扛不住）和低频高价值（用户想不起来）都不好做。</li></ul><h2 id="产品形态" tabindex="-1">产品形态 <a class="header-anchor" href="#产品形态" aria-label="Permalink to &quot;产品形态&quot;">​</a></h2><ul><li><strong>Copilot 型</strong> <span class="prio prio-must">必须</span> — 嵌在现有工作流里做辅助，最容易落地，用户接受度高。</li><li><strong>Agent 型</strong> <span class="prio prio-must">必须</span> — 端到端完成任务，价值高但可靠性难保证。</li><li><strong>工作流自动化型</strong> <span class="prio prio-must">必须</span> — 固定流程 + AI 节点，最稳，ToB 主流。</li><li><strong>知识库问答型</strong> <span class="prio prio-must">必须</span> — RAG 的标准形态，红海但需求真实。</li><li><strong>结构化抽取型</strong> <span class="prio prio-must">必须</span> — 合同、发票、简历、工单。ROI 最容易算清。</li><li><strong>内容生产型</strong> <span class="prio prio-imp">重要</span> — 批量生成 + 人工审核。成本优势明显。</li></ul><h2 id="落地" tabindex="-1">落地 <a class="header-anchor" href="#落地" aria-label="Permalink to &quot;落地&quot;">​</a></h2><ul><li><strong>需求验证方法</strong> <span class="prio prio-must">必须</span> — 先用人工 + 现成模型跑 50 个真实样本，看能不能达到及格线，再谈开发。</li><li><strong>最小可用评测集</strong> <span class="prio prio-must">必须</span> — 项目启动第一周就该有，而不是上线前才做。</li><li><strong>上线门槛定义</strong> <span class="prio prio-must">必须</span> — 量化：准确率 ≥ X%、P95 延迟 ≤ Ys、成本 ≤ Z 元/次。写下来。</li><li><strong>用户预期管理</strong> <span class="prio prio-must">必须</span> — 明确告知能力边界，比事后道歉便宜得多。</li><li><strong>失败时的降级体验</strong> <span class="prio prio-must">必须</span> — 模型不可用时退回搜索/模板/人工，而不是报错白屏。</li><li><strong>成本与定价模型</strong> <span class="prio prio-must">必须</span> — 按次/按 token/订阅。算清毛利再定。</li><li><strong>竞品拆解方法</strong> <span class="prio prio-imp">重要</span> — 用同一批问题测竞品，看它哪里强哪里弱。比看宣传页有用。</li><li><strong>上线后的观察期</strong> <span class="prio prio-imp">重要</span> — 前两周每天看 badcase，比任何评测集都真实。</li></ul>',11)])])}const m=a(i,[["render",n]]);export{d as __pageData,m as default};
